import {chromium} from '@playwright/test';import fs from 'node:fs/promises';import {KEY,scenarioState,makeTask} from '../src/model.js';
const dir='检查记录/全站查缺补漏_20261022',browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true,args:['--no-proxy-server']}),p=await browser.newPage({viewport:{width:1440,height:1000}}),rows=[],errors=[];p.on('pageerror',e=>errors.push(e.message));p.setDefaultTimeout(5000);
async function visit(route,s){await p.goto('http://127.0.0.1:5184/plan',{waitUntil:'domcontentloaded'});await p.evaluate(({s,k})=>{localStorage.setItem(k,JSON.stringify(s));localStorage.setItem('career-prototype-operation-guide-v1',JSON.stringify({enabled:false,neverPrompt:true}));},{s,k:KEY});await p.goto('http://127.0.0.1:5184'+route,{waitUntil:'domcontentloaded'});}
try{await visit('/assistant?tab=自然语言检索',scenarioState('PT01'));await p.getByLabel('描述需求',{exact:true}).fill('想了解前端开发');await p.getByRole('button',{name:'生成模拟筛选草稿',exact:true}).click();rows.push({case:'前端查询',actual:await p.getByLabel('方向',{exact:true}).inputValue(),expected:'frontend'});await p.screenshot({path:dir+'/审查截图/缺陷-检索方向.png'});
const s=scenarioState('PT05');s.tasks.push({...makeTask(s,{title:'另一任务（合成）',hours:1,purpose:'另一问题'}),id:'another',status:'完成',completed:true,note:'另一任务结果'});await visit('/work/task-demo?tab=完成回执',s);await p.getByRole('button',{name:'稍后确认，先复盘',exact:true}).click();rows.push({case:'原任务进入复盘',actual:await p.getByLabel('关联实际任务',{exact:true}).inputValue(),expected:'task-demo'});
const bad=scenarioState('PT05');bad.compare=['data','removed-career'];await visit('/careers?tab=比较',bad);rows.push({case:'旧比较方向ID',errors:[...errors],body:(await p.locator('body').innerText()).slice(0,120)});
await p.setViewportSize({width:390,height:844});for(const route of ['/app','/assessment','/assessment?tab=原文确认','/assessment?tab=四维与差距','/assessment?tab=成果档案','/careers','/careers?tab=比较','/careers?tab=企业与岗位','/careers?tab=我的机会','/career-map','/plan','/plan?tab=执行&view=calendar','/learning','/work/task-demo?tab=尝试与反馈','/reports','/reports?tab=岗位简历','/assistant','/assistant?tab=自然语言检索','/settings','/settings?tab=资料与隐私']){await visit(route,scenarioState('PT05'));await p.locator('.page-surface').waitFor();rows.push({case:'手机',route,overflow:await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth)});}
}finally{await fs.writeFile(dir+'/初始边界审查.json',JSON.stringify({rows,errors},null,2));await browser.close();}console.log(JSON.stringify({rows,errors}));
